// Generated by esquadro: do not edit. A record's page, and how a field's
// value is shown (yours too, from src/fields.ts).
import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query"
import { Link, useNavigate } from "@tanstack/react-router"
import { Copy, Pencil, Trash2 } from "lucide-react"
import { fields as yours } from "@/fields.ts"
import { Badge } from "@/components/ui/badge"
import { Button } from "@/components/ui/button"
import { Card, CardContent } from "@/components/ui/card"
import { Skeleton } from "@/components/ui/skeleton"
import { api } from "../api.ts"
import { resources } from "../resources.gen.ts"
import { ask } from "./confirm.tsx"
import { useDuplicate } from "./duplicate.ts"
import { describe } from "./errors.ts"
import { capitalize, format, t } from "./i18n.ts"
import type { FieldMeta, Rec, ResourceMeta } from "./meta.ts"
import { ResourceList } from "./list.tsx"
import { PageHeader } from "./page.tsx"
import { DetailSkeleton, ErrorState } from "./states.tsx"
import { Highlight } from "./search.tsx"
import type { Resource } from "./resource.ts"
import { toast } from "./toast.tsx"

/** A field's value: your own renderer for its name or kind, or the kit's. */
export function FieldValue({ field, record }: { field: FieldMeta; record: Rec }) {
  const value = record[field.name]
  const own = yours[field.name] ?? yours[field.kind]
  if (own?.show) return <>{own.show(value, record)}</>
  if (field.kind === "enum" && value) return <Badge variant="secondary">{format(field, value)}</Badge>
  if (field.kind === "bool") return <Badge variant={value ? "default" : "outline"}>{format(field, value)}</Badge>
  if (field.kind === "relation" && value) {
    const related = record[field.name.replace(/_id$/, "")] as Rec | undefined
    if (related && field.display) return <>{String(related[field.display] ?? related.id)}</>
    return <RelationValue field={field} id={String(value)} />
  }
  if (value === null || value === undefined || value === "") return <span className="text-muted-foreground">—</span>
  if (field.kind === "text" || field.kind === "textarea") return <Highlight text={format(field, value)} />
  return <>{format(field, value)}</>
}

/** A related record, by the field it is shown by: fetched once, then cached. */
function RelationValue({ field, id }: { field: FieldMeta; id: string }) {
  const target = (resources as unknown as Record<string, ResourceMeta>)[field.target ?? ""]
  const related = useQuery({
    queryKey: [target?.name ?? field.target, "get", id],
    queryFn: () => target.api(api as never).get(id),
    enabled: target !== undefined,
    staleTime: 60_000,
  })
  if (related.isPending && target) return <Skeleton className="inline-block h-4 w-24 align-middle" />
  const shown = related.data?.[field.display ?? "id"]
  if (shown === undefined || shown === null) return <span className="text-muted-foreground">{id.slice(0, 8)}</span>
  const text = capitalize(String(shown))
  return (
    <Link
      to={`/${target.name}/${id}` as never}
      className="font-medium underline-offset-4 hover:underline"
      onClick={(e) => e.stopPropagation()}
    >
      {text}
    </Link>
  )
}

/** Back to the resource's list. */
export function BackToList({ resource }: { resource: Resource }) {
  return (
    <Button variant="outline" asChild>
      <Link to={`/${resource.meta.name}` as never}>{t("backTo", { name: resource.meta.label })}</Link>
    </Button>
  )
}

/** A record of the resource; none without an id (a create). */
export function useRecord(resource: Resource, id: string | undefined) {
  return useQuery({
    queryKey: [resource.meta.name, "get", id],
    queryFn: () => resource.meta.api(api as never).get(id ?? ""),
    enabled: id !== undefined,
  })
}

export function ResourceShow({ resource, id }: { resource: Resource; id: string }) {
  const { meta } = resource
  const record = useRecord(resource, id)
  const duplicate = useDuplicate(meta)
  const navigate = useNavigate()
  const queryClient = useQueryClient()
  const remove = useMutation({
    mutationFn: (r: Rec) => meta.api(api as never).delete(r.id, { ifMatch: r }),
    onSuccess: () => {
      toast(t("deleted"))
      queryClient.invalidateQueries({ queryKey: [meta.name] })
      navigate({ to: `/${meta.name}` as never })
    },
    onError: (e) => toast(describe(e), "error"),
  })
  if (record.isPending) return <DetailSkeleton fields={(resource.show ?? resource.form).length} />
  if (record.isError) return <ErrorState error={record.error} onRetry={() => record.refetch()} back={<BackToList resource={resource} />} />
  const r = record.data
  const can = r.can ?? []
  const title = resource.title ? String(r[resource.title.name] ?? "") : meta.singular
  return (
    <div className="flex flex-col gap-6">
      <PageHeader
        title={title}
        description={capitalize(meta.singular)}
        actions={
          <>
            {resource.actions
              ?.filter((a) => !a.when || a.when(r))
              .map((a) => (
                <Button
                  key={a.label}
                  variant="outline"
                  onClick={async () => {
                    if (a.confirm && !(await ask(a.confirm))) return
                    try {
                      await a.run(r)
                      toast(t("done"))
                      queryClient.invalidateQueries({ queryKey: [meta.name] })
                    } catch (e) {
                      toast(describe(e), "error")
                    }
                  }}
                >
                  {a.label}
                </Button>
              ))}
            <Button variant="outline" onClick={() => duplicate(r)}>
              <Copy /> {t("duplicate")}
            </Button>
            {can.includes("update") && (
              <Button variant="outline" asChild>
                <Link to={`/${meta.name}/${r.id}/edit` as never}>
                  <Pencil /> {t("edit")}
                </Link>
              </Button>
            )}
            {can.includes("delete") && (
              <Button
                variant="destructive"
                disabled={remove.isPending}
                onClick={async () => (await ask(t("confirmDelete"), { destructive: true })) && remove.mutate(r)}
              >
                <Trash2 /> {t("delete")}
              </Button>
            )}
          </>
        }
      />
      <Card>
        <CardContent>
          <dl className="grid gap-x-8 gap-y-6 sm:grid-cols-2">
            {(resource.show ?? resource.form).map((f) => (
              <div key={f.name} className="space-y-1">
                <dt className="text-sm text-muted-foreground">{f.label}</dt>
                <dd className="text-sm font-medium">
                  <FieldValue field={f} record={r} />
                </dd>
              </div>
            ))}
          </dl>
        </CardContent>
      </Card>
      {resource.relations?.().map((rel) => (
        <section key={`${rel.resource.meta.name}-${rel.param}`} className="flex flex-col gap-3">
          <ResourceList resource={rel.resource} scope={ { param: rel.param, value: r.id, label: rel.label } } />
        </section>
      ))}
    </div>
  )
}
